import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { casesAPI, dailyRewardsAPI } from '../services/api';
import CaseCard from '../components/CaseCard';
import RewardCard from '../components/RewardCard';
import CaseOpeningAnimation from '../components/CaseOpeningAnimation';
import ImageWithFallback from '../components/ImageWithFallback';

const HomePage = () => {
  const { balance, updateBalance } = useAuth();

  const [cases, setCases] = useState([]);
  const [dailyReward, setDailyReward] = useState(null);
  const [loading, setLoading] = useState(true);

  const [showAnimation, setShowAnimation] = useState(false);
  const [animationCaseId, setAnimationCaseId] = useState(null);
  const [wonItemFromAnimation, setWonItemFromAnimation] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const casesResponse = await casesAPI.getCases();
        setCases(casesResponse.data);

        const rewardResponse = await dailyRewardsAPI.getStatus();
        setDailyReward(rewardResponse.data);
      } catch (error) {
        console.error('Error fetching data:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleOpenCase = (caseId) => {
    setAnimationCaseId(caseId);
    setShowAnimation(true);
  };

  const handleAnimationComplete = async (wonItem) => {
    setWonItemFromAnimation(wonItem);
    await updateBalance();
  };

  const handleAnimationClose = () => {
    setShowAnimation(false);
    setWonItemFromAnimation(null);
    setAnimationCaseId(null);
  };

  const handleClaimDailyReward = async () => {
    try {
      const response = await dailyRewardsAPI.claimReward();

      setDailyReward(null);
      await updateBalance();

      alert(`You claimed ${response.data.reward_amount} €!`);
    } catch (error) {
      console.error('Error claiming daily reward:', error);

      alert(
        'Error claiming daily reward: ' +
        (error.response?.data?.detail || error.message || 'Request failed')
      );
    }
  };

  if (loading) {
    return (
      <div className="container">
        <div className="text-center py-5">
          <div className="spinner-border text-primary" role="status">
            <span className="visually-hidden">Loading...</span>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container">

      {/* Header */}
      <div className="row mb-5">
        <div className="col-md-8">
          <h1 className="display-4 gradient-text">
            Welcome to WellCase
          </h1>

          <p className="lead">
            Open virtual cases. Collect skins. Upgrade your inventory.
          </p>

          <div className="bg-info">
            Virtual currency — no real-money value
          </div>
        </div>
      </div>

      {/* Daily Reward */}
      {dailyReward && (
        <div className="row mb-5">
          <div className="col-md-4">
            <RewardCard
              dayStreak={dailyReward.dayStreak || 0}
              rewardAmount={dailyReward.reward_amount || 0}
              onClaim={handleClaimDailyReward}
            />
          </div>
        </div>
      )}

      {/* Popular Cases */}
      <div className="mb-5">
        <h2 className="mb-4">
          Popular Cases
        </h2>

        <div className="row g-4">
          {cases.map((caseItem) => (
            <div
              key={caseItem.id}
              className="col-md-4"
            >
              <CaseCard
                case={caseItem}
                onOpen={handleOpenCase}
              />
            </div>
          ))}
        </div>
      </div>

      {/* Case Opening Animation */}
      {showAnimation && (
        <div
          className="opening-overlay active"
          onClick={handleAnimationClose}
        >
          <div
            className="opening-overlay-content"
            onClick={(e) => e.stopPropagation()}
          >
            <CaseOpeningAnimation
              caseId={animationCaseId}
              onComplete={handleAnimationComplete}
              onClose={handleAnimationClose}
            />
          </div>
        </div>
      )}

      {/* Won Item Celebration */}
      {wonItemFromAnimation && !showAnimation && (
        <div
          className="celebration-overlay active"
          onClick={() => setWonItemFromAnimation(null)}
        >
          <div
            className="celebration-content"
            onClick={(e) => e.stopPropagation()}
          >
            <h3>Congratulations!</h3>

            <p>
              You won: {wonItemFromAnimation.name}
            </p>

            <div className="won-item-image">
              <ImageWithFallback
                src={wonItemFromAnimation.image_url}
                alt={wonItemFromAnimation.name}
                className="celebration-item-image"
                style={{
                  width: '120px',
                  height: '120px'
                }}
              />
            </div>
          </div>
        </div>
      )}

    </div>
  );
};

export default HomePage;
